<script setup lang="ts">
import {ref,computed} from 'vue';import PageShell from '../../components/PageShell.vue';import EmptyState from '../../components/EmptyState.vue';import {usePage} from '../../composables/usePage';import {request} from '../../utils/request';import {go,money,time,status} from '../../utils/format';const rows=ref<any[]>([]),filter=ref('AVAILABLE');const {loading,error,load}=usePage(async()=>rows.value=(await request('/coupons/mine?size=100')).list);const visible=computed(()=>rows.value.filter(c=>(c.status==='AVAILABLE'&&Date.parse(c.expires_at)<=Date.now()?'EXPIRED':c.status)===filter.value))
</script><template><PageShell title="我的优惠券" back :loading="loading" :error="error" @retry="load"><view class="row" style="margin-bottom:22px"><view class="title">小小心意，<br/>照顾更轻松。</view><text class="link" @click="go('owner/claim')">去领券 ›</text></view><view class="tabs"><view v-for="s in ['AVAILABLE','USED','EXPIRED','LOCKED']" :key="s" :class="['tab',{active:filter===s}]" @click="filter=s">{{status(s)}}</view></view><view class="card" v-for="c in visible" :key="c.id"><view class="row"><text class="amount">{{money(c.amount)}}</text><view><view>满 {{money(c.threshold)}} 可用</view><text class="muted">{{c.source==='push'?'平台赠送':'自主领取'}}</text></view></view><view class="divider"/><text class="muted">有效期至 {{time(c.expires_at)}}</text></view><EmptyState v-if="!visible.length" text="当前分类暂无优惠券"/></PageShell></template>
